const subject = $json.subject || '';
const from = $json.from?.value?.[0]?.address || $json.from || 'unknown';
const text = [subject, $json.snippet || '', $json.textPlain || ''].join('\n');
const amountMatch = text.match(/(?:EUR|GBP|USD|€|£|\$)\s?([0-9]+(?:[.,][0-9]{2})?)/i);
const invoiceMatch = text.match(/invoice(?:\s*#|\s*no\.?|\s*:)?\s*([A-Z0-9-]{3,})/i);
const dueMatch = text.match(/due(?:\s+date)?\s*[:\-]?\s*([0-9]{4}-[0-9]{2}-[0-9]{2}|[0-9]{2}\/[0-9]{2}\/[0-9]{4})/i);

return {
  json: {
    receivedAt: new Date().toISOString(),
    vendorEmail: from,
    invoiceRef: invoiceMatch?.[1] || 'TODO_MANUAL',
    amountDetected: amountMatch?.[1] || 'TODO_MANUAL',
    dueDateDetected: dueMatch?.[1] || 'TODO_MANUAL',
    subject
  }
};
